fn match_regex(pattern: &[u8], text: &[u8], pi: usize, ti: usize) -> bool {
    if pi == pattern.len() {
        return true; // End of pattern means match (anywhere in text for partial match)
    }

    // Handle end anchor
    if pi < pattern.len() && pattern[pi] == b'$' && pi == pattern.len() - 1 {
        return ti == text.len();
    }

    // Handle start anchor
    if pi == 0 && pi < pattern.len() && pattern[pi] == b'^' {
        return match_regex(pattern, text, pi + 1, ti);
    }

    // Try matching from current position
    do_match(pattern, text, pi, ti) || 
    // Try matching from next position in text (for non-anchored patterns)
    {
        if pattern.first() == Some(&b'^') {
            false
        } else if ti < text.len() {
            match_regex(pattern, text, pi, ti + 1)
        } else {
            false
        }
    }
}

fn do_match(pattern: &[u8], text: &[u8], pi: usize, ti: usize) -> bool {
    if pi >= pattern.len() {
        return true;
    }

    let p = pattern[pi];

    // Handle end anchor
    if p == b'$' {
        return ti == text.len() && pi == pattern.len() - 1;
    }

    // Handle start anchor at beginning
    if p == b'^' {
        return do_match(pattern, text, pi + 1, ti);
    }

    // Check for quantifier after current char
    let next_p = if pi + 1 < pattern.len() { Some(pattern[pi + 1]) } else { None };

    match next_p {
        Some(b'*') => {
            // Match zero times
            if do_match(pattern, text, pi + 2, ti) {
                return true;
            }
            // Match one or more times
            let mut ti2 = ti;
            while ti2 < text.len() && char_matches(p, text[ti2]) {
                ti2 += 1;
                if do_match(pattern, text, pi + 2, ti2) {
                    return true;
                }
            }
            false
        }
        Some(b'+') => {
            // Match one or more times
            if ti >= text.len() || !char_matches(p, text[ti]) {
                return false;
            }
            let mut ti2 = ti + 1;
            if do_match(pattern, text, pi + 2, ti2) {
                return true;
            }
            while ti2 < text.len() && char_matches(p, text[ti2]) {
                ti2 += 1;
                if do_match(pattern, text, pi + 2, ti2) {
                    return true;
                }
            }
            false
        }
        Some(b'?') => {
            // Match zero or one time
            if do_match(pattern, text, pi + 2, ti) {
                return true;
            }
            if ti < text.len() && char_matches(p, text[ti]) {
                do_match(pattern, text, pi + 2, ti + 1)
            } else {
                false
            }
        }
        _ => {
            if ti < text.len() && char_matches(p, text[ti]) {
                do_match(pattern, text, pi + 1, ti + 1)
            } else {
                false
            }
        }
    }
}

fn char_matches(pattern_char: u8, text_char: u8) -> bool {
    if pattern_char == b'.' {
        text_char != b'\n'
    } else {
        pattern_char == text_char
    }
}

struct Config {
