    num: Option<usize>,
    offset: i64,
    until_contains: Option<String>,
    until_error: Option<i32>,
    until_match: Option<String>,
    until_time: Option<String>,

    // Command
    cmd: Vec<String>,
}

impl Config {
    fn new() -> Self {
        Config {
            error_duration: false,
            only_last: false,
            stdin_flag: false,
            summary: false,
            until_changes: false,
            until_fail: false,
            until_same: false,
