    let mut show_help = false;
    let mut show_version = false;
    let mut i = 0;
    let mut end_of_flags = false;

    while i < args.len() {
        let arg = &args[i];

        if end_of_flags {
            config.cmd.push(arg.clone());
            i += 1;
            continue;
        }

        match arg.as_str() {
            "--" => {
                end_of_flags = true;
                i += 1;
            }
            "-h" | "--help" => {
                show_help = true;
                i += 1;
            }
            "-V" | "--version" => {
                show_version = true;
                i += 1;
            }
            "-D" | "--error-duration" => {
                config.error_duration = true;
