                i += 1;
            }
            "-s" | "--until-success" => {
                config.until_success = true;
                i += 1;
            }
            "-b" | "--count-by" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--count-by requires an argument"));
                }
                config.count_by = args[i].parse().map_err(|_| format!("Invalid count-by: {}", args[i]))?;
                i += 1;
            }
            "-e" | "--every" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--every requires an argument"));
                }
                config.every = parse_duration(&args[i])?;
                i += 1;
            }
            "--for" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--for requires an argument"));
                }
                config.ffor = Some(args[i].clone());
                i += 1;
            }
            "-d" | "--for-duration" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--for-duration requires an argument"));
                }
                config.for_duration = Some(parse_duration(&args[i])?);
                i += 1;
