            "-n" | "--num" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--num requires an argument"));
                }
                config.num = Some(args[i].parse().map_err(|_| format!("Invalid num: {}", args[i]))?);
                i += 1;
            }
            "-o" | "--offset" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--offset requires an argument"));
                }
                config.offset = args[i].parse().map_err(|_| format!("Invalid offset: {}", args[i]))?;
                i += 1;
            }
            "-c" | "--until-contains" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-contains requires an argument"));
                }
                config.until_contains = Some(args[i].clone());
                i += 1;
            }
            "-r" | "--until-error" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-error requires an argument"));
