fn parse_duration(s: &str) -> Result<Duration, String> {
    let mut total_nanos: u128 = 0;
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();

    if chars.is_empty() {
        return Ok(Duration::from_nanos(0));
    }

    while i < chars.len() {
        // Parse number
        let start = i;
        while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
            i += 1;
        }
        if i == start {
            return Err(format!("Invalid duration: {}", s));
        }

        let num_str: String = chars[start..i].iter().collect();
        let num: f64 = num_str.parse().map_err(|_| format!("Invalid number in duration: {}", s))?;

        // Parse unit
        let unit_start = i;
        while i < chars.len() && chars[i].is_alphabetic() {
            i += 1;
        }
        let unit: String = chars[unit_start..i].iter().collect();

        let nanos = match unit.as_str() {
            "h" => (num * 3_600_000_000_000.0) as u128,
            "m" => (num * 60_000_000_000.0) as u128,
            "s" => (num * 1_000_000_000.0) as u128,
            "ms" => (num * 1_000_000.0) as u128,
            "us" => (num * 1_000.0) as u128,
            _ => return Err(format!("Unknown unit '{}' in duration: {}", unit, s)),
        };

        total_nanos += nanos;
    }

    Ok(Duration::from_nanos(total_nanos as u64))
}

