fn text_matches_pattern(pattern: &str, text: &str) -> bool {
    // Simple regex matching: support ^ $ . * + ? [] | ()
    // This needs to be a proper implementation
    // Let's implement NFA-based regex

    // For simplicity, let's implement a recursive backtracking regex
