fn match_regex(pattern: &[u8], text: &[u8], pi: usize, ti: usize) -> bool {
    if pi == pattern.len() {
        return true; // End of pattern means match (anywhere in text for partial match)
    }

    // Handle end anchor
    if pi < pattern.len() && pattern[pi] == b'$' && pi == pattern.len() - 1 {
        return ti == text.len();
    }

    // Handle start anchor
    if pi == 0 && pi < pattern.len() && pattern[pi] == b'^' {
        return match_regex(pattern, text, pi + 1, ti);
    }

    // Try matching from current position
    do_match(pattern, text, pi, ti) || 
    // Try matching from next position in text (for non-anchored patterns)
    {
        if pattern.first() == Some(&b'^') {
            false
        } else if ti < text.len() {
            match_regex(pattern, text, pi, ti + 1)
        } else {
            false
        }
    }
}

fn do_match(pattern: &[u8], text: &[u8], pi: usize, ti: usize) -> bool {
    if pi >= pattern.len() {
        return true;
    }

    let p = pattern[pi];

    // Handle end anchor
    if p == b'$' {
        return ti == text.len() && pi == pattern.len() - 1;
    }

    // Handle start anchor at beginning
    if p == b'^' {
        return do_match(pattern, text, pi + 1, ti);
    }

    // Check for quantifier after current char
    let next_p = if pi + 1 < pattern.len() { Some(pattern[pi + 1]) } else { None };

    match next_p {
        Some(b'*') => {
            // Match zero times
            if do_match(pattern, text, pi + 2, ti) {
                return true;
            }
            // Match one or more times
            let mut ti2 = ti;
            while ti2 < text.len() && char_matches(p, text[ti2]) {
                ti2 += 1;
                if do_match(pattern, text, pi + 2, ti2) {
                    return true;
                }
            }
            false
        }
        Some(b'+') => {
            // Match one or more times
            if ti >= text.len() || !char_matches(p, text[ti]) {
                return false;
            }
            let mut ti2 = ti + 1;
            if do_match(pattern, text, pi + 2, ti2) {
                return true;
            }
            while ti2 < text.len() && char_matches(p, text[ti2]) {
                ti2 += 1;
                if do_match(pattern, text, pi + 2, ti2) {
                    return true;
                }
            }
            false
        }
        Some(b'?') => {
            // Match zero or one time
            if do_match(pattern, text, pi + 2, ti) {
                return true;
            }
            if ti < text.len() && char_matches(p, text[ti]) {
                do_match(pattern, text, pi + 2, ti + 1)
            } else {
                false
            }
        }
        _ => {
            if ti < text.len() && char_matches(p, text[ti]) {
                do_match(pattern, text, pi + 1, ti + 1)
            } else {
                false
            }
        }
    }
}

fn char_matches(pattern_char: u8, text_char: u8) -> bool {
    if pattern_char == b'.' {
        text_char != b'\n'
    } else {
        pattern_char == text_char
    }
}

struct Config {
    // Flags
    error_duration: bool,
    only_last: bool,
    stdin_flag: bool,
    summary: bool,
    until_changes: bool,
    until_fail: bool,
    until_same: bool,
    until_success: bool,

    // Options
    count_by: i64,
    every: Duration,
    ffor: Option<String>,
    for_duration: Option<Duration>,
    num: Option<usize>,
    offset: i64,
    until_contains: Option<String>,
    until_error: Option<i32>,
    until_match: Option<String>,
    until_time: Option<String>,

    // Command
    cmd: Vec<String>,
}

impl Config {
    fn new() -> Self {
        Config {
            error_duration: false,
            only_last: false,
            stdin_flag: false,
            summary: false,
            until_changes: false,
            until_fail: false,
            until_same: false,
            until_success: false,
            count_by: 1,
            every: Duration::from_nanos(1000), // 1us
            ffor: None,
            for_duration: None,
            num: None,
            offset: 0,
            until_contains: None,
            until_error: None,
            until_match: None,
            until_time: None,
            cmd: Vec::new(),
        }
    }
}

fn parse_args(args: &[String]) -> Result<(Config, bool, bool), String> {
    let mut config = Config::new();
    let mut show_help = false;
    let mut show_version = false;
    let mut i = 0;
    let mut end_of_flags = false;

    while i < args.len() {
        let arg = &args[i];

        if end_of_flags {
            config.cmd.push(arg.clone());
            i += 1;
            continue;
        }

        match arg.as_str() {
            "--" => {
                end_of_flags = true;
                i += 1;
            }
            "-h" | "--help" => {
                show_help = true;
                i += 1;
            }
            "-V" | "--version" => {
                show_version = true;
                i += 1;
            }
            "-D" | "--error-duration" => {
                config.error_duration = true;
                i += 1;
            }
            "-l" | "--only-last" => {
                config.only_last = true;
                i += 1;
            }
            "-i" | "--stdin" => {
                config.stdin_flag = true;
                i += 1;
            }
            "--summary" => {
                config.summary = true;
                i += 1;
            }
            "-C" | "--until-changes" => {
                config.until_changes = true;
                i += 1;
            }
            "-f" | "--until-fail" => {
                config.until_fail = true;
                i += 1;
            }
            "-S" | "--until-same" => {
                config.until_same = true;
                i += 1;
            }
            "-s" | "--until-success" => {
                config.until_success = true;
                i += 1;
            }
            "-b" | "--count-by" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--count-by requires an argument"));
                }
                config.count_by = args[i].parse().map_err(|_| format!("Invalid count-by: {}", args[i]))?;
                i += 1;
            }
            "-e" | "--every" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--every requires an argument"));
                }
                config.every = parse_duration(&args[i])?;
                i += 1;
            }
            "--for" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--for requires an argument"));
                }
                config.ffor = Some(args[i].clone());
                i += 1;
            }
            "-d" | "--for-duration" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--for-duration requires an argument"));
                }
                config.for_duration = Some(parse_duration(&args[i])?);
                i += 1;
            }
            "-n" | "--num" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--num requires an argument"));
                }
                config.num = Some(args[i].parse().map_err(|_| format!("Invalid num: {}", args[i]))?);
                i += 1;
            }
            "-o" | "--offset" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--offset requires an argument"));
                }
                config.offset = args[i].parse().map_err(|_| format!("Invalid offset: {}", args[i]))?;
                i += 1;
            }
            "-c" | "--until-contains" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-contains requires an argument"));
                }
                config.until_contains = Some(args[i].clone());
                i += 1;
            }
            "-r" | "--until-error" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-error requires an argument"));
                }
                config.until_error = Some(args[i].parse().map_err(|_| format!("Invalid until-error: {}", args[i]))?);
                i += 1;
            }
            "-m" | "--until-match" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-match requires an argument"));
                }
                config.until_match = Some(args[i].clone());
                i += 1;
            }
            "-t" | "--until-time" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("--until-time requires an argument"));
                }
                config.until_time = Some(args[i].clone());
                i += 1;
            }
            _ => {
                // Remaining args are the command
                config.cmd.push(arg.clone());
                end_of_flags = true;
                i += 1;
            }
        }
    }

    Ok((config, show_help, show_version))
}

fn parse_utc_time(s: &str) -> Result<std::time::SystemTime, String> {
    // Parse format: "2018-04-20 04:20:00" (UTC)
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() != 2 {
        return Err(format!("Invalid time format: {}", s));
    }

    let date_parts: Vec<u32> = parts[0].split('-').map(|p| p.parse().unwrap_or(0)).collect();
    let time_parts: Vec<u32> = parts[1].split(':').map(|p| p.parse().unwrap_or(0)).collect();

    if date_parts.len() != 3 || time_parts.len() != 3 {
        return Err(format!("Invalid time format: {}", s));
    }

    let year = date_parts[0] as i64;
    let month = date_parts[1] as u32;
    let day = date_parts[2] as u32;
    let hour = time_parts[0] as u64;
    let minute = time_parts[1] as u64;
    let second = time_parts[2] as u64;

    // Convert to Unix timestamp
    // Use simplified calculation (no leap second handling)
    let days_since_epoch = days_from_civil(year, month, day);
    let secs = days_since_epoch as u64 * 86400 + hour * 3600 + minute * 60 + second;

    Ok(std::time::UNIX_EPOCH + Duration::from_secs(secs))
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    // Algorithm from Howard Hinnant
    let y = y - if m <= 2 { 1 } else { 0 };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as u64; // [0, 399]
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) as u64 + 2) / 5 + d as u64 - 1; // [0, 365]
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy; // [0, 146096]
    era * 146097 + doe as i64 - 719468
}

fn run_command(cmd: &[String], use_shell: bool, env_vars: &[(&str, String)]) -> (String, i32) {
    let mut command = if use_shell {
        let mut c = Command::new("sh");
        c.arg("-c");
        c.arg(&cmd[0]);
        c
    } else {
        let mut c = Command::new(&cmd[0]);
        for arg in &cmd[1..] {
            c.arg(arg);
        }
        c
    };

    // Set environment variables
    for (key, value) in env_vars {
        command.env(key, value);
    }

    // Capture stdout and stderr together
    command.stdout(Stdio::piped());
    command.stderr(Stdio::piped());

    match command.output() {
        Ok(output) => {
            let mut out = String::from_utf8_lossy(&output.stdout).into_owned();
            let err = String::from_utf8_lossy(&output.stderr).into_owned();
            out.push_str(&err);
            let exit_code = output.status.code().unwrap_or(1);
            (out, exit_code)
        }
        Err(e) => {
            (format!("{}\n", e), 1)
        }
    }
}

fn is_stdin_pipe() -> bool {
    // Check if stdin is a pipe (not a terminal)
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        if let Ok(metadata) = std::fs::metadata("/proc/self/fd/0") {
            let file_type = metadata.file_type();
            return file_type.is_fifo() || file_type.is_socket() || 
                   (!file_type.is_char_device() && !file_type.is_block_device());
        }
        // Fallback: try to detect via /proc/self/fd/0 symlink
        if let Ok(link) = std::fs::read_link("/proc/self/fd/0") {
            let s = link.to_string_lossy();
            return !s.contains("/dev/pts/") && !s.contains("/dev/tty");
        }
    }
    false
}

fn main() {
    let all_args: Vec<String> = env::args().collect();
    let prog_name = std::path::Path::new(&all_args[0])
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("loop")
        .to_string();

    let args = &all_args[1..];

    let (config, show_help, show_version) = match parse_args(args) {
        Ok(result) => result,
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    };

    if show_version {
        println!("{}", VERSION);
        return;
    }

    if show_help {
        print_help(&prog_name);
        return;
    }

    if config.cmd.is_empty() {
        println!("No command supplied, exiting.");
        return;
    }

    // Determine if command is single string or multi-arg
    let use_shell = config.cmd.len() == 1;

    // Collect items
    let mut items: Vec<String> = Vec::new();

    if let Some(ref ffor) = config.ffor {
        for item in ffor.split(',') {
            items.push(item.to_string());
        }
    }

    // Read stdin if pipe or --stdin flag
    let stdin_is_pipe = is_stdin_pipe();
    if stdin_is_pipe || config.stdin_flag {
        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_ok() {
            for line in input.lines() {
                items.push(line.to_string());
            }
        }
    }

    let has_items = !items.is_empty();

    // Parse until-time
    let until_time_sys = config.until_time.as_ref().map(|t| {
        parse_utc_time(t).expect("Invalid until-time format")
    });

    // Main loop state
    let mut actual_count: i64 = 0;
    let mut item_index: usize = 0;
    let mut last_item: Option<String> = None;
    let mut last_output: Option<String> = None;
    let mut exit_codes: Vec<i32> = Vec::new();
    let mut buffered_outputs: Vec<String> = Vec::new();
    let mut stopped_by_duration = false;

    let start = Instant::now();
    let stdout = io::stdout();

    loop {
        // PRE-RUN CHECKS

        // Check for-duration
        if let Some(for_dur) = config.for_duration {
            if start.elapsed() >= for_dur {
                stopped_by_duration = true;
                break;
            }
        }

        // Check until-time
        if let Some(ref target_time) = until_time_sys {
            if let Ok(now) = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH) {
                if let Ok(target) = target_time.duration_since(std::time::UNIX_EPOCH) {
                    if now >= target {
                        break;
                    }
                }
            }
        }

        // Get current item
        let current_item = if has_items {
            if item_index < items.len() {
                let item = items[item_index].clone();
                last_item = Some(item.clone());
                item
            } else {
                // Items exhausted
                if config.num.is_none() {
                    break;
                }
                last_item.clone().unwrap_or_default()
            }
        } else {
            String::new()
        };

        // Calculate COUNT
        let count = config.offset + actual_count * config.count_by;

        // Environment variables
        let env_vars: Vec<(&str, String)> = vec![
            ("COUNT", count.to_string()),
            ("ACTUALCOUNT", actual_count.to_string()),
            ("ITEM", current_item.clone()),
        ];

        // Execute command
        let (output, exit_code) = run_command(&config.cmd, use_shell, &env_vars);

        exit_codes.push(exit_code);

        // Handle output
        if config.only_last {
            buffered_outputs.push(output.clone());
        } else {
            if !output.is_empty() {
                let mut out = stdout.lock();
                let _ = out.write_all(output.as_bytes());
                let _ = out.flush();
            }
        }

        // POST-RUN CHECKS
        let mut should_stop = false;

        if let Some(ref contains) = config.until_contains {
            if output.contains(contains.as_str()) {
                should_stop = true;
            }
        }

        if let Some(ref pattern) = config.until_match {
            if text_matches_pattern(pattern, &output) {
                should_stop = true;
            }
        }

        if config.until_changes {
            if let Some(ref prev) = last_output {
                if &output != prev {
                    should_stop = true;
                }
            }
        }

        if config.until_same {
            if let Some(ref prev) = last_output {
                if &output == prev {
                    should_stop = true;
                }
            }
        }

        if config.until_success && exit_code == 0 {
            should_stop = true;
        }

        if config.until_fail && exit_code != 0 {
            should_stop = true;
        }

        if let Some(error_code) = config.until_error {
            if exit_code == error_code {
                should_stop = true;
            }
        }

        last_output = Some(output);
        actual_count += 1;
        item_index += 1;

        // Check --num
        if let Some(n) = config.num {
            if actual_count >= n as i64 {
                should_stop = true;
            }
        }

        if should_stop {
            break;
        }

        // Sleep
        if !config.every.is_zero() {
            std::thread::sleep(config.every);
        }
    }

    // Print buffered output if --only-last
    if config.only_last {
        if let Some(last) = buffered_outputs.last() {
            let mut out = stdout.lock();
            let _ = out.write_all(last.as_bytes());
            let _ = out.flush();
        }
    }

    // Print summary
    if config.summary {
        print_summary(&exit_codes);
    }

    // Determine exit code
    if config.error_duration && stopped_by_duration {
        std::process::exit(124);
    }

    std::process::exit(0);
}
