                if i >= args.len() {
                    return Err("--every requires an argument".to_string());
                }
                config.every = parse_duration(&args[i])?;
                i += 1;
            }
            "--for" => {
                i += 1;
                if i >= args.len() {
                    return Err("--for requires an argument".to_string());
                }
                config.ffor = Some(args[i].clone());
                i += 1;
            }
            "-d" | "--for-duration" => {
                i += 1;
                if i >= args.len() {
                    return Err("--for-duration requires an argument".to_string());
                }
                config.for_duration = Some(parse_duration(&args[i])?);
                i += 1;
            }
            "-n" | "--num" => {
                i += 1;
                if i >= args.len() {
                    return Err("--num requires an argument".to_string());
                }
                config.num = Some(args[i].parse().map_err(|_| format!("Invalid num: {}", args[i]))?);
                i += 1;
            }
            "-o" | "--offset" => {
                i += 1;
                if i >= args.len() {
                    return Err("--offset requires an argument".to_string());
                }
                config.offset = args[i].parse().map_err(|_| format!("Invalid offset: {}", args[i]))?;
                i += 1;
            }
            "-c" | "--until-contains" => {
                i += 1;
                if i >= args.len() {
                    return Err("--until-contains requires an argument".to_string());
                }
                config.until_contains = Some(args[i].clone());
                i += 1;
            }
            "-r" | "--until-error" => {
                i += 1;
                if i >= args.len() {
                    return Err("--until-error requires an argument".to_string());
                }
                config.until_error = Some(args[i].parse().map_err(|_| format!("Invalid until-error: {}", args[i]))?);
                i += 1;
            }
            "-m" | "--until-match" => {
                i += 1;
                if i >= args.len() {
                    return Err("--until-match requires an argument".to_string());
