                config.until_time = Some(args[i].clone());
                i += 1;
            }
            _ => {
                // Check if it looks like a flag (starts with -)
                if arg.starts_with('-') && !end_of_flags {
                    return Err(format!("Unknown option: {}", arg));
                }
                config.cmd.push(arg.clone());
                end_of_flags = true;
                i += 1;
            }
