    offset: i64,
    until_contains: Option<String>,
    until_error: Option<i32>,
    until_match: Option<String>,
    until_time: Option<String>,
    cmd: Vec<String>,
}

impl Config {
    fn new() -> Self {
        Config {
            error_duration: false,
            only_last: false,
            stdin_flag: false,
            summary: false,
            until_changes: false,
            until_fail: false,
            until_same: false,
            until_success: false,
            count_by: 1,
            every: Duration::from_nanos(1000), // 1us
            ffor: None,
