    println!();
    println!("ARGS:");
    println!("    <input>...    The command to be looped");
}

fn print_summary(exit_codes: &[i32]) {
    let total = exit_codes.len();
    let successes = exit_codes.iter().filter(|&&c| c == 0).count();
    let failures = total - successes;
    let failure_codes: Vec<String> = exit_codes.iter()
        .filter(|&&c| c != 0)
        .map(|c| c.to_string())
        .collect();

    println!("Total runs:\t{}", total);
    println!("Successes:\t{}", successes);
    if failure_codes.is_empty() {
        println!("Failures:\t{}", failures);
    } else {
        println!("Failures:\t{} ({})", failures, failure_codes.join(", "));
    }
}

/// Check if pattern matches any line in text
fn matches_pattern(pattern: &str, text: &str) -> bool {
    for line in text.lines() {
        if line_matches(pattern, line) {
            return true;
        }
    }
    // Also handle text that doesn't end with newline
    if !text.ends_with('\n') && line_matches(pattern, text) {
        return true;
    }
    false
}

fn line_matches(pattern: &str, line: &str) -> bool {
    let anchored_start = pattern.starts_with('^');
    let p = if anchored_start { &pattern[1..] } else { pattern };

    if anchored_start {
        match_here(p.as_bytes(), line.as_bytes(), 0)
    } else {
        for i in 0..=line.len() {
            if match_here(p.as_bytes(), line.as_bytes(), i) {
                return true;
            }
        }
        false
    }
}

fn match_here(pattern: &[u8], text: &[u8], start_ti: usize) -> bool {
    let mut pi = 0;
    let mut ti = start_ti;

    loop {
        if pi == pattern.len() {
            return true;
        }

        // Handle $ (end anchor)
        if pattern[pi] == b'$' && pi == pattern.len() - 1 {
            return ti == text.len();
        }

        // Check for quantifier after current char
        let next = pattern.get(pi + 1).copied();

        match next {
            Some(b'*') => {
                // Zero or more - try zero first (greedy later)
                if match_here(&pattern[pi+2..], text, ti) {
                    return true;
                }
                let mut ti2 = ti;
                while ti2 < text.len() && char_match(pattern[pi], text[ti2]) {
                    ti2 += 1;
                    if match_here(&pattern[pi+2..], text, ti2) {
                        return true;
                    }
                }
                return false;
            }
            Some(b'+') => {
                // One or more
                if ti >= text.len() || !char_match(pattern[pi], text[ti]) {
                    return false;
                }
                let mut ti2 = ti + 1;
                if match_here(&pattern[pi+2..], text, ti2) {
                    return true;
                }
                while ti2 < text.len() && char_match(pattern[pi], text[ti2]) {
                    ti2 += 1;
                    if match_here(&pattern[pi+2..], text, ti2) {
                        return true;
                    }
                }
                return false;
            }
            Some(b'?') => {
                // Zero or one
                if ti < text.len() && char_match(pattern[pi], text[ti]) {
                    if match_here(&pattern[pi+2..], text, ti+1) {
                        return true;
                    }
                }
                return match_here(&pattern[pi+2..], text, ti);
            }
            _ => {
                if ti < text.len() && char_match(pattern[pi], text[ti]) {
                    pi += 1;
                    ti += 1;
                } else {
                    return false;
                }
            }
        }
    }
}

fn char_match(p: u8, c: u8) -> bool {
    p == b'.' || p == c
}

struct Config {
    error_duration: bool,
    only_last: bool,
    stdin_flag: bool,
    summary: bool,
    until_changes: bool,
    until_fail: bool,
