/// Check if pattern matches any line in text
fn matches_pattern(pattern: &str, text: &str) -> bool {
    for line in text.lines() {
        if line_matches(pattern, line) {
            return true;
        }
    }
    if !text.ends_with('\n') && line_matches(pattern, text) {
        return true;
    }
    false
}

fn line_matches(pattern: &str, line: &str) -> bool {
    let anchored_start = pattern.starts_with('^');
    let p = if anchored_start { &pattern[1..] } else { pattern };

    if anchored_start {
        match_here(p.as_bytes(), line.as_bytes(), 0)
    } else {
        for i in 0..=line.len() {
            if match_here(p.as_bytes(), line.as_bytes(), i) {
                return true;
            }
        }
        false
    }
}

fn match_here(pattern: &[u8], text: &[u8], start_ti: usize) -> bool {
    let mut pi = 0;
    let mut ti = start_ti;

    loop {
        if pi == pattern.len() {
            return true;
        }

        if pattern[pi] == b'$' && pi == pattern.len() - 1 {
            return ti == text.len();
        }

        let next = pattern.get(pi + 1).copied();

        match next {
            Some(b'*') => {
                if match_here(&pattern[pi+2..], text, ti) {
                    return true;
                }
                let mut ti2 = ti;
                while ti2 < text.len() && char_match(pattern[pi], text[ti2]) {
                    ti2 += 1;
                    if match_here(&pattern[pi+2..], text, ti2) {
                        return true;
                    }
                }
                return false;
            }
            Some(b'+') => {
                if ti >= text.len() || !char_match(pattern[pi], text[ti]) {
                    return false;
                }
                let mut ti2 = ti + 1;
                if match_here(&pattern[pi+2..], text, ti2) {
                    return true;
                }
                while ti2 < text.len() && char_match(pattern[pi], text[ti2]) {
                    ti2 += 1;
                    if match_here(&pattern[pi+2..], text, ti2) {
                        return true;
                    }
                }
                return false;
            }
            Some(b'?') => {
                if ti < text.len() && char_match(pattern[pi], text[ti]) {
                    if match_here(&pattern[pi+2..], text, ti+1) {
                        return true;
                    }
                }
                return match_here(&pattern[pi+2..], text, ti);
            }
            _ => {
                if ti < text.len() && char_match(pattern[pi], text[ti]) {
                    pi += 1;
                    ti += 1;
                } else {
                    return false;
                }
            }
        }
    }
}

fn char_match(p: u8, c: u8) -> bool {
